<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\View\View; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Models\Nest; use Pterodactyl\Models\User; use Pterodactyl\Models\Node; use Pterodactyl\Models\Location; use Pterodactyl\Models\Dezerx\FreeServer; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\ServerCreate\ServerCreate; use Pterodactyl\Services\Dezerx\ServerCreate\ServerFactory; use Pterodactyl\Services\Dezerx\ServerCreate\NodeCapacity; class ServerCreateController extends Controller { private const NUMBERS = [ 'cpu', 'memory', 'swap', 'disk', 'io', 'databases', 'allocations', 'backups', 'per_user', 'total', 'min_account_age_hours', 'renew_every', 'renew_window_hours', 'grace_hours', 'purge_days', 'min_cpu', 'max_cpu', 'pool_cpu', 'min_memory', 'max_memory', 'pool_memory', 'min_disk', 'max_disk', 'pool_disk', 'min_databases', 'max_databases', 'pool_databases', 'min_allocations', 'max_allocations', 'pool_allocations', 'min_backups', 'max_backups', 'pool_backups', ]; private const FLAGS = [ 'enabled', 'oom_disabled', 'start_on_completion', 'variables', 'require_totp', 'renew_enabled', 'custom_resources', 'discord_required', ]; private const PLAIN = ['discord_client_id', 'discord_guild_id']; private const SECRETS = ['discord_client_secret', 'discord_bot_token']; public function __construct( private AlertsMessageBag $alert, private ServerFactory $factory, private NodeCapacity $capacity, ) { } public function index(): View { return view('admin.dezerx.servercreate.index', [ 'config' => ServerCreate::all(), 'actions' => ServerCreate::ACTIONS, 'hints' => ServerCreate::ACTION_HINTS, 'units' => ServerCreate::UNITS, 'cpuUnits' => ServerCreate::CPU_UNITS, 'sizeUnits' => ServerCreate::SIZE_UNITS, 'ceilings' => ServerCreate::CEILINGS, 'locations' => Location::query()->withCount('nodes')->orderBy('short')->get(), 'nodes' => Node::query() ->select('id', 'name', 'location_id', 'public', 'memory', 'disk') ->withCount('servers') ->orderBy('location_id') ->orderBy('name') ->get(), 'capacity' => $this->capacity->forLocations( Location::query()->pluck('id')->map(fn ($id) => (int) $id)->all(), ), 'nests' => Nest::query()->with('eggs')->orderBy('name')->get(), 'issued' => FreeServer::query() ->with(['server', 'owner']) ->orderByRaw('renew_at IS NULL, renew_at') ->limit(50) ->get(), 'total' => ServerCreate::issued(), 'timezone' => ServerCreate::timezone(), ]); } public function update(Request $request): RedirectResponse { $data = $request->validate([ 'enabled' => ['sometimes', 'boolean'], 'oom_disabled' => ['sometimes', 'boolean'], 'start_on_completion' => ['sometimes', 'boolean'], 'variables' => ['sometimes', 'boolean'], 'require_totp' => ['sometimes', 'boolean'], 'renew_enabled' => ['sometimes', 'boolean'], 'custom_resources' => ['sometimes', 'boolean'], 'discord_required' => ['sometimes', 'boolean'], 'locations' => ['sometimes', 'array'], 'locations.*' => ['integer'], 'eggs' => ['sometimes', 'array'], 'eggs.*' => ['string', 'max:64'], 'node_limits' => ['sometimes', 'array'], 'node_limits.*' => ['nullable', 'integer', 'min:0'], 'location_notes' => ['sometimes', 'array'], 'location_notes.*' => ['nullable', 'string', 'max:120'], 'renew_unit' => ['sometimes', 'string'], 'expire_action' => ['sometimes', 'string'], 'cpu_unit' => ['sometimes', 'string'], 'memory_unit' => ['sometimes', 'string'], 'disk_unit' => ['sometimes', 'string'], 'name_prefix' => ['sometimes', 'nullable', 'string', 'max:24'], 'cpu' => ['sometimes', 'nullable', 'integer'], 'memory' => ['sometimes', 'nullable', 'integer'], 'swap' => ['sometimes', 'nullable', 'integer'], 'disk' => ['sometimes', 'nullable', 'integer'], 'io' => ['sometimes', 'nullable', 'integer'], 'databases' => ['sometimes', 'nullable', 'integer'], 'allocations' => ['sometimes', 'nullable', 'integer'], 'backups' => ['sometimes', 'nullable', 'integer'], 'per_user' => ['sometimes', 'nullable', 'integer'], 'total' => ['sometimes', 'nullable', 'integer'], 'min_account_age_hours' => ['sometimes', 'nullable', 'integer'], 'renew_every' => ['sometimes', 'nullable', 'integer'], 'renew_window_hours' => ['sometimes', 'nullable', 'integer'], 'grace_hours' => ['sometimes', 'nullable', 'integer'], 'purge_days' => ['sometimes', 'nullable', 'integer'], 'min_cpu' => ['sometimes', 'nullable', 'integer'], 'max_cpu' => ['sometimes', 'nullable', 'integer'], 'pool_cpu' => ['sometimes', 'nullable', 'integer'], 'min_memory' => ['sometimes', 'nullable', 'integer'], 'max_memory' => ['sometimes', 'nullable', 'integer'], 'pool_memory' => ['sometimes', 'nullable', 'integer'], 'min_disk' => ['sometimes', 'nullable', 'integer'], 'max_disk' => ['sometimes', 'nullable', 'integer'], 'pool_disk' => ['sometimes', 'nullable', 'integer'], 'min_databases' => ['sometimes', 'nullable', 'integer'], 'max_databases' => ['sometimes', 'nullable', 'integer'], 'pool_databases' => ['sometimes', 'nullable', 'integer'], 'min_allocations' => ['sometimes', 'nullable', 'integer'], 'max_allocations' => ['sometimes', 'nullable', 'integer'], 'pool_allocations' => ['sometimes', 'nullable', 'integer'], 'min_backups' => ['sometimes', 'nullable', 'integer'], 'max_backups' => ['sometimes', 'nullable', 'integer'], 'pool_backups' => ['sometimes', 'nullable', 'integer'], 'discord_client_id' => ['sometimes', 'nullable', 'string', 'max:64'], 'discord_client_secret' => ['sometimes', 'nullable', 'string', 'max:191'], 'discord_bot_token' => ['sometimes', 'nullable', 'string', 'max:191'], 'discord_guild_id' => ['sometimes', 'nullable', 'string', 'max:32'], ]); $values = []; foreach (self::FLAGS as $flag) { $values[$flag] = (bool) ($data[$flag] ?? false); } foreach (self::NUMBERS as $number) { $values[$number] = array_key_exists($number, $data) ? (int) $data[$number] : ServerCreate::number($number); } $values['locations'] = $this->locations((array) ($data['locations'] ?? [])); $values['eggs'] = $this->eggs((array) ($data['eggs'] ?? [])); $values['node_limits'] = $this->nodeLimits((array) ($data['node_limits'] ?? [])); $values['location_notes'] = $this->locationNotes((array) ($data['location_notes'] ?? [])); $values['renew_unit'] = array_key_exists((string) ($data['renew_unit'] ?? ''), ServerCreate::UNITS) ? (string) $data['renew_unit'] : ServerCreate::UNIT_DAYS; $values['expire_action'] = array_key_exists((string) ($data['expire_action'] ?? ''), ServerCreate::ACTIONS) ? (string) $data['expire_action'] : ServerCreate::ACTION_SUSPEND; $values['cpu_unit'] = array_key_exists((string) ($data['cpu_unit'] ?? ''), ServerCreate::CPU_UNITS) ? (string) $data['cpu_unit'] : ServerCreate::cpuUnit(); foreach (['memory', 'disk'] as $key) { $values[$key . '_unit'] = array_key_exists((string) ($data[$key . '_unit'] ?? ''), ServerCreate::SIZE_UNITS) ? (string) $data[$key . '_unit'] : ServerCreate::sizeUnit($key); } $values['name_prefix'] = trim((string) ($data['name_prefix'] ?? '')); foreach (self::PLAIN as $key) { $values[$key] = trim((string) ($data[$key] ?? '')); } foreach (self::SECRETS as $key) { $typed = trim((string) ($data[$key] ?? '')); $values[$key] = $typed === '' ? (string) ServerCreate::setting($key) : $typed; } ServerCreate::save($values); if ($values['enabled'] && ($values['eggs'] === [] || $values['locations'] === [])) { $this->alert->warning( 'Saved, but the page stays hidden until at least one location and one egg are ticked.', )->flash(); } else { $this->alert->success('Server Create settings have been updated.')->flash(); } return redirect()->route('admin.dezerx.servercreate'); } public function grant(Request $request, User $user): RedirectResponse { $data = $request->validate([ 'own' => ['sometimes', 'array'], 'own.*' => ['nullable', 'integer', 'min:0'], ]); ServerCreate::saveGrant($user, (array) ($data['own'] ?? [])); $this->alert->success( 'What ' . e($user->username) . ' may spend on their own servers has been saved.' )->flash(); return redirect()->route('admin.users.view', $user->id); } public function renew(FreeServer $entry): RedirectResponse { $this->factory->renew($entry); $this->alert->success('That server has been renewed.')->flash(); return redirect()->route('admin.dezerx.servercreate'); } public function release(FreeServer $entry): RedirectResponse { $entry->delete(); $this->alert->success('That server is no longer tracked and will not fall due again.')->flash(); return redirect()->route('admin.dezerx.servercreate'); } private function locations(array $wanted): array { return Location::query() ->whereIn('id', array_map('intval', $wanted)) ->pluck('id') ->map(fn ($id) => (int) $id) ->values() ->all(); } private function nodeLimits(array $wanted): array { $known = Node::query()->pluck('id')->map(fn ($id) => (int) $id)->all(); $out = []; foreach ($wanted as $node => $limit) { $node = (int) $node; if (in_array($node, $known, true) && (int) $limit > 0) { $out[$node] = (int) $limit; } } return $out; } private function locationNotes(array $wanted): array { $known = Location::query()->pluck('id')->map(fn ($id) => (int) $id)->all(); $out = []; foreach ($wanted as $location => $note) { $location = (int) $location; $note = trim((string) $note); if (in_array($location, $known, true) && $note !== '') { $out[$location] = $note; } } return $out; } private function eggs(array $wanted): array { return \Pterodactyl\Models\Egg::query() ->whereIn('uuid', array_map('strval', $wanted)) ->pluck('uuid') ->map(fn ($uuid) => (string) $uuid) ->values() ->all(); } } 